```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    """Abstract base class defining the template method for sorting algorithms"""

    def sort(self, data: List[Any]) -> List[Any]:
        """Template method that defines the sorting algorithm skeleton"""
        if len(data) <= 1:
            return data

        # Make a copy to avoid modifying original data
        sorted_data = data.copy()
        self._sort_implementation(sorted_data)
        return sorted_data

    @abstractmethod
    def _sort_implementation(self, data: List[Any]) -> None:
        """Abstract method to be implemented by subclasses"""
        pass

    @abstractmethod
    def compare(self, a: Any, b: Any) -> bool:
        """Compare two elements - returns True if a should come before b"""
        pass

    def swap(self, data: List[Any], i: int, j: int) -> None:
        """Swap elements at positions i and j"""
        data[i], data[j] = data[j], data[i]


class BubbleSort(SortAlgorithm):
    """Concrete implementation of Bubble Sort algorithm"""

    def _sort_implementation(self, data: List[Any]) -> None:
        n = len(data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if not self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
                    swapped = True
            if not swapped:
                break

    def compare(self, a: Any, b: Any) -> bool:
        """Returns True if a <= b (for ascending order)"""
        return a <= b


class SelectionSort(SortAlgorithm):
    """Concrete implementation of Selection Sort algorithm"""

    def _sort_implementation(self, data: List[Any]) -> None:
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if not self.compare(data[min_idx], data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(data, i, min_idx)

    def compare(self, a: Any, b: Any) -> bool:
        """Returns True if a <= b (for ascending order)"""
        return a <= b


# Testing the implementation
if __name__ == "__main__":
    # Test with integers
    int_data = [64, 34, 25, 12, 22, 11, 90]

    bubble_sort = BubbleSort()
    sorted_int_bubble = bubble_sort.sort(int_data)
    print(f"BubbleSort (integers): {sorted_int_bubble}")

    selection_sort = SelectionSort()
    sorted_int_selection = selection_sort.sort(int_data)
    print(f"SelectionSort (integers): {sorted_int_selection}")

    # Test with strings
    str_data = ["banana", "apple", "cherry", "date"]

    sorted_str_bubble = bubble_sort.sort(str_data)
    print(f"BubbleSort (strings): {sorted_str_bubble}")

    sorted_str_selection = selection_sort.sort(str_data)
    print(f"SelectionSort (strings): {sorted_str_selection}")

    # Verify original data is unchanged
    print(f"Original data: {int_data}")
    print(f"Original string data: {str_data}")
```

